let m:integer = UInt(CRm[0] :: op2[2:0]);

if !IsFeatureImplemented(FEAT_AMUv1) then
    Undefined();
elsif m >= NUM_AMU_CG1_MONITORS then
    Undefined();
elsif !IsG1ActivityMonitorImplemented(m) then
    Undefined();
elsif HaveEL(EL3) && PSTATE.EL != EL3 && EL3SDDUndefPriority() && CPTR_EL3().TAM == '1' then
    Undefined();
elsif PSTATE.EL == EL0 then
    if AMUSERENR_EL0().EN == '0' then
        AArch64_SystemAccessTraptoEL1orEL2(0x18);
    elsif EL2Enabled() && CPTR_EL2().TAM == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && EffectivelyAtEL0NotInHost() && IsFeatureImplemented(FEAT_FGT) && (!HaveEL(EL3) || SCR_EL3().FGTEn == '1') && HAFGRTR_EL2()[(2 * m) + 19] == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif HaveEL(EL3) && CPTR_EL3().TAM == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    else
        X{64}(t) = AMEVTYPER1_EL0(m);
    end;
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && CPTR_EL2().TAM == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_FGT) && (!HaveEL(EL3) || SCR_EL3().FGTEn == '1') && HAFGRTR_EL2()[(2 * m) + 19] == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif HaveEL(EL3) && CPTR_EL3().TAM == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    else
        X{64}(t) = AMEVTYPER1_EL0(m);
    end;
elsif PSTATE.EL == EL2 then
    if HaveEL(EL3) && CPTR_EL3().TAM == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    else
        X{64}(t) = AMEVTYPER1_EL0(m);
    end;
elsif PSTATE.EL == EL3 then
    X{64}(t) = AMEVTYPER1_EL0(m);
end;

let m:integer = UInt(CRm[0] :: op2[2:0]);

if !IsFeatureImplemented(FEAT_AMUv1) then
    Undefined();
elsif m >= NUM_AMU_CG1_MONITORS then
    Undefined();
elsif !IsG1ActivityMonitorImplemented(m) then
    Undefined();
elsif IsHighestEL(PSTATE.EL) && !ImpDefBool("AMEVCNTR1_EL0()[m] is fixed") then
    AMEVTYPER1_EL0(m) = X{64}(t);
else
    Undefined();
end;
